"""Formatting helpers for values exposed by the MiniJinja CLI."""
import json
import math


def _plain(value):
    if value is None:
        return None
    if isinstance(value, (str, int, float, bool)):
        return value
    if isinstance(value, dict):
        return {str(k): _plain(v) for k, v in value.items()}
    if isinstance(value, (tuple, list, range)):
        return [_plain(v) for v in value]
    return str(value)


def display(value):
    """MiniJinja's human readable value representation (used in expressions)."""
    if value is None:
        return "none"
    if value is True:
        return "true"
    if value is False:
        return "false"
    if isinstance(value, str):
        return value
    if isinstance(value, float):
        if math.isnan(value):
            return "NaN"
        if math.isinf(value):
            return "inf" if value > 0 else "-inf"
        return repr(value)
    if isinstance(value, dict):
        return "{" + ", ".join(json.dumps(str(k), ensure_ascii=False) + ": " + display(v) for k, v in value.items()) + "}"
    if isinstance(value, (list, tuple, range)):
        return "[" + ", ".join(display(v) if not isinstance(v, str) else json.dumps(v, ensure_ascii=False) for v in value) + "]"
    return str(value)


def json_output(value, pretty=False):
    """Serialize a template value as JSON, mapping none to JSON null."""
    return json.dumps(_plain(value), ensure_ascii=False, indent=2 if pretty else None,
                      separators=None if pretty else (",", ":"), allow_nan=False)
